   424	function readWorkerProposalInvocationPrivateKey(
   425	  env: NodeJS.ProcessEnv,
   426	): string | undefined {
   427	  const rawFd = env.LATTICE_MANAGED_HOST_WORKER_CAPABILITY_FD?.trim();
   428	  if (!rawFd) return undefined;
   429	  const fd = Number(rawFd);
   430	  if (!Number.isInteger(fd) || fd < 3 || fd > 255) {
   430	  if (!Number.isInteger(fd) || fd < 3 || fd > 255) {
   431	    throw new Error('managed host run worker: proposal capability fd must be between 3 and 255');
   432	  }
   433	  const stat = fstatSync(fd);
   434	  if (stat.isFile()) {
   435	    throw new Error('managed host run worker: proposal capability must arrive over a non-file descriptor');
   436	  }
   437	  const key = readFileSync(fd, 'utf8').trim();
   438	  if (!/^[A-Za-z0-9+/]{43}=$/.test(key)) {
   439	    throw new Error('managed host run worker: proposal capability descriptor is malformed');
   440	  }
   441	  return key;
   442	}
