   305	  dir: string,
   306	  cap: number,
   307	  staleMs: number,
   308	  now: number,
   309	  meta: ProviderProcessSlotMeta,
   310	  lockTiming: ProviderRegistryLockTiming = {},
   311	): AcquiredProviderProcessSlot | null {
   312	  mkdirSync(dir, { recursive: true });
   313	  const boundedCap = Number.isFinite(cap) && Number.isInteger(cap) && cap > 0
   314	    ? cap
   315	    : PROVIDER_PROCESS_MAX_CONCURRENT_DEFAULT;
   316	  return withProviderRegistryLock(dir, () => {
   317	    const live = scanLiveProviderProcessSlotsUnlocked(dir, now, staleMs);
   318	    if (live.length >= boundedCap) return null;
   319	    const token = randomUUID();
   320	    const record: ProviderProcessSlotFileMeta = { ...meta, token };
   321	    for (let index = 0; index < boundedCap; index += 1) {
   322	      const file = join(dir, `slot-${index}.json`);
   323	      if (writeProviderProcessSlotExclusive(file, record)) return { file, token };
   324	      const judged = readSlotOccupant(file);
   325	      if (!slotReclaimable(judged, file, now, staleMs)) continue;
   326	      if (judged.state !== 'missing') {
   327	        if (!sameSlotOccupant(readSlotOccupant(file), judged)) continue;
   328	        try { unlinkSync(file); } catch { /* exclusive recreate decides the winner */ }
   329	      }
   330	      if (writeProviderProcessSlotExclusive(file, record)) return { file, token };
   331	    }
   332	    return null;
   333	  }, lockTiming);
   334	}
