   131	function normalizeString(value: unknown): string {
   132	  return typeof value === 'string' ? value.trim() : '';
   133	}
   134	
   135	function optionalPositiveInteger(command: string, field: string, value: unknown): number | undefined {
   136	  if (value === undefined) return undefined;
   137	  if (typeof value !== 'number' || !Number.isFinite(value) || !Number.isInteger(value) || value <= 0) {
   138	    throw new Error(`${command}: --${field} must be a finite positive integer`);
   139	  }
   140	  return value;
   141	}
   142	
   143	function optionalNonnegativeInteger(
   144	  command: string,
   145	  field: string,
   146	  value: unknown,
   147	  maximum?: number,
   148	): number | undefined {
   149	  if (value === undefined) return undefined;
   150	  if (typeof value !== 'number'
   151	    || !Number.isFinite(value)
   152	    || !Number.isInteger(value)
   153	    || value < 0
   154	    || (maximum !== undefined && value > maximum)) {
   155	    const maximumClause = maximum === undefined ? '' : ` <= ${maximum}`;
   156	    throw new Error(`${command}: --${field} must be a finite nonnegative integer${maximumClause}`);
   157	  }
   158	  return value;
   159	}
