   165	function normalizeHost(raw: string): HostRunHost {
   166	  const value = raw.trim().toLowerCase();
   167	  if (value === 'codex') return 'codex';
   168	  if (value === 'claude' || value === 'claude-code') return 'claude';
   169	  throw new Error(`host_run: unsupported host "${raw}" (expected codex | claude)`);
   170	}
