   176	/** Format the single stderr usage-summary / refusal line. */
   177	function formatUsageLine(result: HostRunResult): string {
   178	  const u = result.usageSummary;
   179	  if (result.blocked) {
   180	    if (result.refusalReason === 'concurrency_cap_exceeded') {
   181	      const list = (result.liveRuns ?? [])
   182	        .map((r) => `  - pid ${r.pid} ${r.host}${r.storyId ? ` story ${r.storyId}` : ''} agentType ${r.agentType} startedAt ${r.startedAt}`)
   183	        .join('\n');
   184	      return `host_run refused: ${u.reason ?? 'concurrency_cap_exceeded'}${list ? `\n${list}` : ''}`;
   185	    }
   186	    return `host_run refused: ${u.reason ?? result.refusalReason ?? 'blocked'}`;
   187	  }
   188	  if (u.recorded === 'disabled') return 'usage ledger disabled (LATTICE_USAGE_LEDGER=0); no rows recorded';
   189	  if (u.recorded === 'provider-reported') {
   190	    const recordId = u.recordId ? ` (recordId ${u.recordId})` : '';
   191	    return `usage recorded: provider=${u.provider ?? 'unknown'} input=${u.input ?? 'null'} cacheRead=${u.cacheRead ?? 'null'} output=${u.output ?? 'null'}${recordId}`;
   192	  }
   193	  if (u.recorded === 'unavailable') {
   194	    return `usage recorded: unavailable (${u.reason ?? 'no usage surface'})`;
   195	  }
   196	  return `usage: ${u.reason ?? 'not recorded'}`;
   197	}
