   211	    timedOut: run.state === 'timed_out',
   212	    timeoutKind: run.state === 'timed_out' ? 'total_timeout' : null,
   213	    terminalReason: run.state === 'completed' ? 'completed' : run.state === 'cancelled' ? 'aborted' : run.state === 'timed_out' ? 'total_timeout' : 'child_error',
