   253	      const promptFilePath = normalizeString(args.promptFile);
   254	      const hasPromptFile = promptFilePath.length > 0;
   255	      let promptText: string;
   256	      let formalReviewBinding: {
   257	        headHash: string;
   258	        materialHash: string;
   259	        storyFilesHash: string;
   260	        promptHash: string;
   261	        envelopeId: string | null;
   262	      } | null = null;
   263	      if (args.managedReview === true) {
   264	        if (hasPrompt || hasPromptFile) {
   265	          throw new Error('host_run: --managedReview derives the exact prompt from ReviewRun; do not pass --prompt or --promptFile');
   266	        }
   267	        if (!storyId || !reviewRunId || !lane || agentType !== lane) {
   268	          throw new Error('host_run: --managedReview requires storyId, reviewRunId, lane, and agentType equal to that lane');
   269	        }
   270	        const story = ctx.store.readStory(storyId);
   271	        const reviewRun = assertCurrentReviewRunForEvidence(ctx.store, story, ctx.root, lane, reviewRunId);
   272	        const storyFilesHash = reviewRun.storyFilesHash ?? reviewRun.workspaceBinding?.storyFilesHash ?? '';
   273	        if (!storyFilesHash) throw new Error('host_run: --managedReview requires a ReviewRun with storyFilesHash binding');
   274	        promptText = buildManagedReviewerPrompt(reviewRun.workspaceBinding?.metadataRoot ?? ctx.root, reviewRun);
   275	        formalReviewBinding = {
   276	          headHash: reviewRun.headHash,
   277	          materialHash: reviewRun.materialHash,
   278	          storyFilesHash,
   279	          promptHash: reviewRun.promptHash,
   280	          envelopeId: reviewRun.envelopeId ?? null,
   281	        };
