   431	      // pathologically wedged stream, we revert to the pre-fix crash window (a
   432	      // post-removal EPIPE could still be unhandled). Every real closed/broken pipe
   433	      // settles its write callback (with or without error) well within this cap, so
   434	      // in practice drainPending resolves as soon as the last chunk's EPIPE lands.
   435	      const DRAIN_CAP_MS = 2000;
   436	      const drainPending = (): Promise<void> => {
   437	        if (pendingWrites <= 0) return Promise.resolve();
